-- Questões originais de estudo baseadas em Date, tradução da 8ª edição (2004).
-- Não são questões oficiais do CP-T nem exercícios transcritos do livro.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens são rascunhos: revise no painel antes de publicar.
-- Páginas referem-se ao arquivo PDF fornecido, não à paginação impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve os registros deste lote.
-- As explicações acompanham o contexto histórico da edição, quando pertinente.
-- Capítulo 11: Dependências funcionais — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('e61bbb5a-c810-55a0-98f7-87a36590b7d2', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'A dependência funcional A → B estabelece que:', '["Tuplas iguais em A devem ser iguais em B.","B deve ser chave primária.","A precisa ser numérico.","Tuplas iguais em B devem ser iguais em A.","A e B devem ter o mesmo tipo."]'::jsonb, 0, 'A determina B, mas a dependência inversa não é implicada automaticamente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.2, páginas 560–563 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('01d18e48-3108-52ac-bd50-5bfd50f755c4', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Qual par de tuplas viola A → B?', '["(A=4,B=7) e (A=5,B=7).","(A=5,B=9) e (A=6,B=9).","(A=4,B=7) e (A=5,B=9).","(A=4,B=7) e (A=6,B=7).","(A=4,B=7) e (A=4,B=9)."]'::jsonb, 4, 'O mesmo determinante A aparece associado a valores distintos de B.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.2, páginas 560–563 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ac656162-e5bc-534d-bbfd-3c243b82a0a0', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Fácil', 'Qual dependência é trivial?', '["C → B, com B e C distintos.","A → B, com A e B distintos.","{A,B} → A.","A → C, com A e C distintos.","B → A, com A e B distintos."]'::jsonb, 2, 'Uma DF é trivial quando o dependente é subconjunto do determinante.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.3, páginas 564 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('492ac750-7ead-54ca-b640-8c4d41bb1f4a', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Fácil', 'A DF {A,B} → {A,B} é válida em qualquer relvar com esses atributos por:', '["Uma ordenação física.","Reflexividade.","Uma política de acesso.","Transitividade entre três atributos distintos.","Uma chave estrangeira obrigatória."]'::jsonb, 1, 'Todo conjunto de atributos determina seus próprios subconjuntos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.3, páginas 564 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('48d8da50-e56d-55e6-b733-b74a48e74472', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'De A → B e B → C, qual DF pode ser inferida?', '["B → A.","A → C.","C → B.","C → A.","C → {A,B}."]'::jsonb, 1, 'A transitividade permite encadear as duas determinações.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.4, páginas 565–567 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('16691aeb-deae-5a0c-83a0-9ff16ac0dc7a', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'De A → B, a regra de aumento permite inferir:', '["B → C.","C → A.","{A,C} → {B,C}.","C → B.","B → A."]'::jsonb, 2, 'Acrescentar os mesmos atributos aos dois lados preserva a dependência.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.4, páginas 565–567 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4f2bdc47-0528-566c-885c-579b950c4321', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'De A → B e A → C, pode-se inferir:', '["C → A.","B → C.","C → B.","A → {B,C}.","B → A."]'::jsonb, 3, 'A regra de união reúne dependentes do mesmo determinante.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.4, páginas 565–567 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6a76b786-a84b-5c2d-bfc2-2ecc10146bfb', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'De A → {B,C}, pode-se inferir:', '["B → C e C → B.","B → A e C → A.","B → A apenas.","A → B e A → C.","C → A apenas."]'::jsonb, 3, 'A decomposição separa os atributos do lado direito.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.4, páginas 565–567 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a2b59d76-49d5-5cad-927e-f8545f911cbf', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'O fecho F+ de um conjunto F de DFs contém:', '["Todas as DFs logicamente implicadas por F.","Apenas as chaves estrangeiras.","Somente as DFs textualmente listadas em F.","As tuplas atualmente armazenadas.","Somente DFs não triviais."]'::jsonb, 0, 'O fecho inclui também consequências e dependências triviais.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.4, páginas 565–567 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('948994a0-5098-5e51-9360-09a7b2f33ca7', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Em R(A,B,C), com A → B e B → C, o fecho de A é:', '["{B,C}.","{A}.","{A,B}.","{A,B,C}.","Vazio."]'::jsonb, 3, 'Começa-se por A e aplicam-se as DFs até não acrescentar novos atributos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.5, páginas 568–570 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0cbc97c5-0bc2-5d6a-8ad2-c1d0a01eba83', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Difícil', 'Em R(A,B,C), somente com A → B, qual é C+?', '["Vazio.","{B,C}.","{A,B,C}.","{A,C}.","{C}."]'::jsonb, 4, 'Nenhuma DF disponível permite obter A ou B a partir de C.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.5, páginas 568–570 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('23dc5f1f-a5a6-5f46-9f34-6f24af63589c', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Difícil', 'Em R(A,B,C), com A → B, qual conjunto é chave candidata?', '["{C}.","{A}.","{A,C}.","{B,C}.","{B}."]'::jsonb, 2, 'A e C juntos determinam tudo; nenhum deles isoladamente determina todos os atributos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.5, páginas 568–570 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4b6b60f8-0e13-5c55-bdc9-3d7f63942866', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Em R(A,B,C), com A → B e B → C, A é:', '["Chave candidata.","Uma superchave não mínima.","Um dependente que não determina nada.","Apenas chave estrangeira.","Um atributo necessariamente redundante."]'::jsonb, 0, 'A+ contém todos os atributos, e seu único subconjunto próprio é vazio, que não os determina neste caso.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.5, páginas 568–570 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9e43892e-4e5f-5cfb-b4e4-d05918c50ab7', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Um conjunto X cujo fecho contém todos os atributos de R é:', '["Sempre uma chave candidata mínima.","Uma tupla da relação.","Sempre uma DF trivial.","Necessariamente uma chave estrangeira.","Uma superchave de R."]'::jsonb, 4, 'Para ser chave candidata, X ainda precisa ser irredutível.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.5, páginas 568–570 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a5b32566-c0bb-5c71-afea-4cee7b94f5be', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Dois conjuntos de DFs são equivalentes quando:', '["Usam a mesma ordem textual.","Possuem apenas atributos numéricos.","Possuem o mesmo fecho.","Têm o mesmo número de dependências.","Foram definidos pelo mesmo usuário."]'::jsonb, 2, 'Equivalência depende das consequências lógicas, não da forma de apresentação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.6, páginas 571–574 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('509f9f63-4626-5ccd-b18c-3ff7722947c0', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Uma DF redundante em F pode ser removida quando:', '["Não aparece em um índice.","Possui dois atributos no determinante.","Usa uma letra repetida em outra DF.","É a primeira da lista.","Ela já é implicada pelas outras DFs de F."]'::jsonb, 4, 'A remoção deve preservar o conjunto de dependências implicadas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.6, páginas 571–574 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0fac0546-d506-526a-9573-cb5b207fefa8', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Em F={A → B, B → C, A → C}, qual DF é redundante?', '["Todas, independentemente umas das outras.","A → C.","A → B.","Nenhuma.","B → C."]'::jsonb, 1, 'A → C já decorre da transitividade das outras duas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.6, páginas 571–574 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f267b81f-e7b9-5043-a8c9-497a84d12701', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Difícil', 'Um conjunto irredutível de DFs deve evitar:', '["A existência de chaves candidatas.","Dependências e atributos supérfluos.","Toda aplicação de transitividade.","Toda dependência não trivial.","Qualquer atributo determinante."]'::jsonb, 1, 'Irredutibilidade busca uma cobertura equivalente sem componentes desnecessários.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.6, páginas 571–574 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3b768f32-bc54-5f1e-81e7-71b8d977a107', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Observar poucas linhas sem violação comprova que A → B é uma regra do domínio?', '["Não; a regra deve valer para todos os estados admissíveis.","Sim, se B for texto.","Sim, se houver índice em A.","Sim, duas linhas sempre bastam.","Não, porque DFs só se aplicam a uma linha."]'::jsonb, 0, 'Um estado pode satisfazer acidentalmente uma DF que não é uma restrição do domínio.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.2, páginas 560–563 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d157c5e5-a7c5-5dff-ad9e-95980ebc5cdf', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Difícil', 'Para testar se X → Y é implicada por F, pode-se verificar se:', '["X está ordenado fisicamente.","X e Y têm a mesma quantidade de atributos.","Y é numérico.","Y está contido em X+ calculado sob F.","F possui mais de três DFs."]'::jsonb, 3, 'O cálculo de fecho de atributos permite testar implicação sem enumerar todo F+.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.5, páginas 568–570 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
